type TJSToken = struct {
	Fval int32
	Fptr uintptr
	Fu   struct {
		Fnum [0]struct {
			Fval TJSValue
		}
		Fident [0]struct {
			Fatom        TJSAtom
			Fhas_escape  TBOOL
			Fis_reserved TBOOL
		}
		Fregexp [0]struct {
			Fbody  TJSValue
			Fflags TJSValue
		}
		Fstr struct {
			Fstr TJSValue
			Fsep int32
		}
		F__ccgo_pad4 [8]byte
	}
}

type TJSParseState = struct {
	Fctx                 uintptr
	Ffilename            uintptr
	Ftoken               TJSToken
	Fgot_lf              TBOOL
	Flast_ptr            uintptr
	Fbuf_start           uintptr
	Fbuf_ptr             uintptr
	Fbuf_end             uintptr
	Fcur_func            uintptr
	Fis_module           TBOOL
	Fallow_html_comments TBOOL
	Fext_json            TBOOL
	Fget_line_col_cache  TGetLineColCache
}

