func _js_parse_array_literal(tls *libc.TLS, s uintptr) (r int32) {
	var idx Tuint32_t
	var need_length TBOOL
	_, _ = idx, need_length
	if _next_token(tls, s) != 0 {
		return -int32(1)
	}
	/* small regular arrays are created on the stack */
	idx = uint32(0)
	for (*TJSParseState)(unsafe.Pointer(s)).Ftoken.Fval != int32(']') && idx < uint32(32) {
		if (*TJSParseState)(unsafe.Pointer(s)).Ftoken.Fval == int32(',') || (*TJSParseState)(unsafe.Pointer(s)).Ftoken.Fval == int32(ETOK_ELLIPSIS) {
			break
		}
		if _js_parse_assign_expr(tls, s) != 0 {
			return -int32(1)
		}
		idx++
		/* accept trailing comma */
		if (*TJSParseState)(unsafe.Pointer(s)).Ftoken.Fval == int32(',') {
			if _next_token(tls, s) != 0 {
				return -int32(1)
			}
		} else {
			if (*TJSParseState)(unsafe.Pointer(s)).Ftoken.Fval != int32(']') {
				goto done
			}
		}
	}
	_emit_op(tls, s, uint8(EOP_array_from))
	_emit_u16(tls, s, uint16(idx))
	/* larger arrays and holes are handled with explicit indices */
	need_length = MFALSE
	for (*TJSParseState)(unsafe.Pointer(s)).Ftoken.Fval != int32(']') && idx < uint32(0x7fffffff) {
		if (*TJSParseState)(unsafe.Pointer(s)).Ftoken.Fval == int32(ETOK_ELLIPSIS) {
			break
		}
		need_length = int32(MTRUE)
		if (*TJSParseState)(unsafe.Pointer(s)).Ftoken.Fval != int32(',') {
			if _js_parse_assign_expr(tls, s) != 0 {
				return -int32(1)
			}
			_emit_op(tls, s, uint8(EOP_define_field))
			_emit_u32(tls, s, ___JS_AtomFromUInt32(tls, idx))
			need_length = MFALSE
		}
		idx++
		/* accept trailing comma */
		if (*TJSParseState)(unsafe.Pointer(s)).Ftoken.Fval == int32(',') {
			if _next_token(tls, s) != 0 {
				return -int32(1)
			}
		}
	}
	if (*TJSParseState)(unsafe.Pointer(s)).Ftoken.Fval == int32(']') {
		if need_length != 0 {
			/* Set the length: Cannot use OP_define_field because
			   length is not configurable */
			_emit_op(tls, s, uint8(EOP_dup))
			_emit_op(tls, s, uint8(EOP_push_i32))
			_emit_u32(tls, s, idx)
			_emit_op(tls, s, uint8(EOP_put_field))
			_emit_atom(tls, s, uint32(EJS_ATOM_length))
		}
		goto done
	}
	/* huge arrays and spread elements require a dynamic index on the stack */
	_emit_op(tls, s, uint8(EOP_push_i32))
	_emit_u32(tls, s, idx)
	/* stack has array, index */
	for (*TJSParseState)(unsafe.Pointer(s)).Ftoken.Fval != int32(']') {
		if (*TJSParseState)(unsafe.Pointer(s)).Ftoken.Fval == int32(ETOK_ELLIPSIS) {
			if _next_token(tls, s) != 0 {
				return -int32(1)
			}
			if _js_parse_assign_expr(tls, s) != 0 {
				return -int32(1)
			}
			_emit_op(tls, s, uint8(EOP_append))
		} else {
			need_length = int32(MTRUE)
			if (*TJSParseState)(unsafe.Pointer(s)).Ftoken.Fval != int32(',') {
				if _js_parse_assign_expr(tls, s) != 0 {
					return -int32(1)
				}
				/* a idx val */
				_emit_op(tls, s, uint8(EOP_define_array_el))
				need_length = MFALSE
			}
			_emit_op(tls, s, uint8(EOP_inc))
		}
		if (*TJSParseState)(unsafe.Pointer(s)).Ftoken.Fval != int32(',') {
			break
		}
		if _next_token(tls, s) != 0 {
			return -int32(1)
		}
	}
	if need_length != 0 {
		/* Set the length: cannot use OP_define_field because
		   length is not configurable */
		_emit_op(tls, s, uint8(EOP_dup1)) /* array length - array array length */
		_emit_op(tls, s, uint8(EOP_put_field))
		_emit_atom(tls, s, uint32(EJS_ATOM_length))
	} else {
		_emit_op(tls, s, uint8(EOP_drop)) /* array length - array */
	}
	goto done
done:
	;
	return _js_parse_expect(tls, s, int32(']'))
	return r
}

