type TPutLValueEnum = int32

const EPUT_LVALUE_NOKEEP = 0
const /* [depth] v -> */
EPUT_LVALUE_NOKEEP_DEPTH = 1
const /* [depth] v -> , keep depth (currently
   just disable optimizations) */
EPUT_LVALUE_KEEP_TOP = 2
const /* [depth] v -> v */
EPUT_LVALUE_KEEP_SECOND = 3
const /* [depth] v0 v -> v0 */
EPUT_LVALUE_NOKEEP_BOTTOM = 4

// C documentation
//
//	/* name has a live reference. 'is_let' is only used with opcode =
//	   OP_scope_get_var which is never generated by get_lvalue(). */
func _put_lvalue(tls *libc.TLS, s uintptr, opcode int32, scope int32, name TJSAtom, label int32, special TPutLValueEnum, is_let TBOOL) {
	var v1 int32
	_ = v1
	switch opcode {
	case int32(EOP_get_field):
		fallthrough
	case int32(EOP_scope_get_private_field):
		/* depth = 1 */
		switch special {
		case int32(EPUT_LVALUE_NOKEEP):
			fallthrough
		case int32(EPUT_LVALUE_NOKEEP_DEPTH):
		case int32(EPUT_LVALUE_KEEP_TOP):
			_emit_op(tls, s, uint8(EOP_insert2)) /* obj v -> v obj v */
		case int32(EPUT_LVALUE_KEEP_SECOND):
			_emit_op(tls, s, uint8(EOP_perm3)) /* obj v0 v -> v0 obj v */
		case int32(EPUT_LVALUE_NOKEEP_BOTTOM):
			_emit_op(tls, s, uint8(EOP_swap))
		default:
			libc.Xabort(tls)
		}
	case int32(EOP_get_array_el):
		fallthrough
	case int32(EOP_get_ref_value):
		/* depth = 2 */
		if opcode == int32(EOP_get_ref_value) {
			x_JS_FreeAtom(tls, (*TJSParseState)(unsafe.Pointer(s)).Fctx, name)
			_emit_label(tls, s, label)
		}
		switch special {
		case int32(EPUT_LVALUE_NOKEEP):
			_emit_op(tls, s, uint8(EOP_nop)) /* will trigger optimization */
		case int32(EPUT_LVALUE_NOKEEP_DEPTH):
		case int32(EPUT_LVALUE_KEEP_TOP):
			_emit_op(tls, s, uint8(EOP_insert3)) /* obj prop v -> v obj prop v */
		case int32(EPUT_LVALUE_KEEP_SECOND):
			_emit_op(tls, s, uint8(EOP_perm4)) /* obj prop v0 v -> v0 obj prop v */
		case int32(EPUT_LVALUE_NOKEEP_BOTTOM):
			_emit_op(tls, s, uint8(EOP_rot3l))
		default:
			libc.Xabort(tls)
		}
	case int32(EOP_get_super_value):
		/* depth = 3 */
		switch special {
		case int32(EPUT_LVALUE_NOKEEP):
			fallthrough
		case int32(EPUT_LVALUE_NOKEEP_DEPTH):
		case int32(EPUT_LVALUE_KEEP_TOP):
			_emit_op(tls, s, uint8(EOP_insert4)) /* this obj prop v -> v this obj prop v */
		case int32(EPUT_LVALUE_KEEP_SECOND):
			_emit_op(tls, s, uint8(EOP_perm5)) /* this obj prop v0 v -> v0 this obj prop v */
		case int32(EPUT_LVALUE_NOKEEP_BOTTOM):
			_emit_op(tls, s, uint8(EOP_rot4l))
		default:
			libc.Xabort(tls)
		}
	default:
		break
	}
	switch opcode {
	case int32(EOP_scope_get_var): /* val -- */
		if is_let != 0 {
			v1 = int32(EOP_scope_put_var_init)
		} else {
			v1 = int32(EOP_scope_put_var)
		}
		_emit_op(tls, s, libc.Uint8FromInt32(v1))
		_emit_u32(tls, s, name) /* has refcount */
		_emit_u16(tls, s, libc.Uint16FromInt32(scope))
	case int32(EOP_get_field):
		_emit_op(tls, s, uint8(EOP_put_field))
		_emit_u32(tls, s, name) /* name has refcount */
	case int32(EOP_scope_get_private_field):
		_emit_op(tls, s, uint8(EOP_scope_put_private_field))
		_emit_u32(tls, s, name) /* name has refcount */
		_emit_u16(tls, s, libc.Uint16FromInt32(scope))
	case int32(EOP_get_array_el):
		_emit_op(tls, s, uint8(EOP_put_array_el))
	case int32(EOP_get_ref_value):
		_emit_op(tls, s, uint8(EOP_put_ref_value))
	case int32(EOP_get_super_value):
		_emit_op(tls, s, uint8(EOP_put_super_value))
	default:
		libc.Xabort(tls)
	}
}

